// Three checks, all here so you can tune them:
// 1. same supplier and same invoice number, same amount: an exact duplicate
// 2. same supplier and same number, different amount: a resend or a correction to look at
// 3. same supplier, same amount, a different number, dated close together: a likely double bill
// Supplier names and invoice numbers are normalised first, so "ACME Supplies Ltd" meets
// "Acme Supplies Limited" and "INV-000123" meets "123".
const s = $('Settings').first().json;
const tolerance = Number(s.amountTolerance) || 0.01;
const windowDays = Number(s.dateWindowDays) || 45;

const normSupplier = v => String(v ?? '').toLowerCase().replace(/&/g, ' and ')
  .replace(/\b(the|ltd|limited|llp|plc|inc|co|company)\b\.?/g, ' ')
  .replace(/[^a-z0-9]+/g, ' ').trim();
const normNumber = v => String(v ?? '').toUpperCase().replace(/[^A-Z0-9]/g, '')
  .replace(/^(INVOICE|INV|NO|NUMBER)+/, '').replace(/^0+(?=\d)/, '');
const money = v => {
  if (v === '' || v == null) return null;
  const n = Number(String(v).replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : null;
};
const parseDate = v => {
  const t = String(v ?? '').trim();
  const uk = t.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{2,4})$/);
  if (uk) {
    const y = uk[3].length === 2 ? 2000 + Number(uk[3]) : Number(uk[3]);
    return Date.UTC(y, Number(uk[2]) - 1, Number(uk[1]));
  }
  const iso = Date.parse(t);
  return Number.isFinite(iso) ? iso : null;
};
const day = ms => (ms == null ? '' : new Date(ms).toISOString().slice(0, 10));

const rows = $('Read The Invoices').all().map((i, idx) => {
  const r = i.json || {};
  return {
    row: idx + 2,
    supplierText: String(r[s.supplierColumn] ?? '').trim(),
    numberText: String(r[s.numberColumn] ?? '').trim(),
    supplier: normSupplier(r[s.supplierColumn]),
    number: normNumber(r[s.numberColumn]),
    amount: money(r[s.amountColumn]),
    date: parseDate(r[s.dateColumn]),
  };
}).filter(r => r.supplier);

const key = r => [r.supplier, r.number, r.amount, day(r.date)].join('|');
const out = [];
const seenPairs = new Set();
for (let i = 0; i < rows.length; i++) {
  for (let j = i + 1; j < rows.length; j++) {
    const a = rows[i], b = rows[j];
    if (a.supplier !== b.supplier) continue;
    const sameAmount = a.amount != null && b.amount != null && Math.abs(a.amount - b.amount) <= tolerance;
    let verdict = '';
    if (a.number && a.number === b.number) {
      verdict = sameAmount ? 'EXACT DUPLICATE' : 'SAME NUMBER, DIFFERENT AMOUNT';
    } else if (sameAmount && a.amount > 0 && a.date != null && b.date != null
               && Math.abs(a.date - b.date) / 86400000 <= windowDays) {
      verdict = 'SAME AMOUNT, DIFFERENT NUMBER';
    }
    if (!verdict) continue;
    const pairKey = [key(a), key(b)].sort().join(' || ');
    if (seenPairs.has(pairKey)) continue; // two copies of one invoice would raise the same pair twice
    seenPairs.add(pairKey);
    out.push({ json: {
      flagged_at: new Date().toISOString(),
      verdict,
      supplier: a.supplierText,
      invoice_a: a.numberText,
      invoice_b: b.numberText,
      amount_a: a.amount,
      amount_b: b.amount,
      date_a: day(a.date),
      date_b: day(b.date),
      sheet_rows: a.row + ' and ' + b.row,
      pair_key: pairKey,
    } });
  }
}
return out;

// A pair you have already been told about is not news. Only new pairs go on.
const flagged = new Set($('Read Already Flagged').all().map(i => String((i.json || {}).pair_key || '')).filter(Boolean));
return $('Find Duplicates').all().filter(i => !flagged.has(i.json.pair_key));

// One Slack message per run, however many pairs were found.
const pairs = $input.all().map(i => i.json);
const lines = pairs.slice(0, 15).map(p =>
  '- ' + p.verdict + ': ' + p.supplier + ' ' + (p.invoice_a || 'no number') + ' / ' + (p.invoice_b || 'no number')
  + ' (' + p.amount_a + (p.amount_a === p.amount_b ? '' : ' vs ' + p.amount_b) + ', rows ' + p.sheet_rows + ')');
if (pairs.length > 15) lines.push('...and ' + (pairs.length - 15) + ' more in the sheet.');
return [{ json: { count: pairs.length, text: ':rotating_light: *' + pairs.length + ' possible duplicate invoice pair(s). Check before anyone pays them.*\n' + lines.join('\n') } }];
